import io
from rich.console import Console
from rich.file_proxy import FileProxy

def test_isatty_behavior():
    # Create a dummy file that has isatty() returning True
    class MockFile(io.TextIOBase):
        def isatty(self):
            return True
        def fileno(self):
            return 1
        def write(self, s):
            return len(s)
        def flush(self):
            pass

    mock_file = MockFile()

    # Case 1: Console is terminal
    console_terminal = Console(force_terminal=True)
    proxy_terminal = FileProxy(console_terminal, mock_file)
    print(f"Console terminal=True, Proxy isatty(): {proxy_terminal.isatty()}")

    # Case 2: Console is NOT terminal
    console_not_terminal = Console(force_terminal=False)
    proxy_not_terminal = FileProxy(console_not_terminal, mock_file)
    print(f"Console terminal=False, Proxy isatty(): {proxy_not_terminal.isatty()}")

if __name__ == "__main__":
    test_isatty_behavior()

